<?php
/** iOS design: Human Interface Guidelines, navigation, SF Symbols and typography, system colours, materials and accessibility. */

return [
    'id' => 'ios-design', 'family' => 'ios', 'after' => 'ui-base', 'categories' => ['design', 'mobile'],
    'title' => L('Design per iOS', 'iOS Design'), 'short' => L('Design iOS', 'iOS Design'), 'level' => L('Intermedio', 'Intermediate'),
    'desc' => L('Le Human Interface Guidelines di Apple: principi, struttura e navigazione delle app, SF Pro, Dynamic Type e SF Symbols, colori di sistema e materiali, controlli e accessibilità.', 'Apple’s Human Interface Guidelines: principles, app structure and navigation, SF Pro, Dynamic Type and SF Symbols, system colours and materials, controls and accessibility.'),
    'lessons' => [
        lesson('hig', L('Le Human Interface Guidelines', 'The Human Interface Guidelines'), [
            P('Le **Human Interface Guidelines** (HIG) sono le linee guida di Apple per iPhone, iPad, Mac, Apple Watch, Apple TV e Vision Pro. Tre idee guidano il design: **gerarchia** (i controlli stanno sopra il contenuto e lo lasciano protagonista), **armonia** (forme e movimenti in sintonia con l’hardware e il sistema) e **coerenza** (comportamenti che gli utenti conoscono già da altre app).', 'The **Human Interface Guidelines** (HIG) are Apple’s guidelines for iPhone, iPad, Mac, Apple Watch, Apple TV and Vision Pro. Three ideas drive the design: **hierarchy** (controls sit above content and leave it centre stage), **harmony** (shapes and motion in tune with hardware and system) and **consistency** (behaviours users already know from other apps).'),
            P('Su iOS si costruisce con **SwiftUI** (o UIKit): i componenti di sistema seguono già le HIG e si aggiornano con il sistema operativo, compreso l’aspetto in **Liquid Glass** con materiali traslucidi che lasciano intravedere il contenuto. Personalizzare va bene per il brand, ma non per cambiare il funzionamento dei controlli standard.', 'On iOS you build with **SwiftUI** (or UIKit): system components already follow the HIG and update with the operating system, including the **Liquid Glass** look with translucent materials letting content show through. Customising is fine for the brand, but not to change how standard controls work.'),
        ], [
            Q('h1', L('Che cosa sono le HIG?', 'What are the HIG?'), [L('Le linee guida di design di Apple', 'Apple’s design guidelines'), L('Un linguaggio di programmazione', 'A programming language'), L('Un’app di disegno', 'A drawing app'), L('Le regole dell’App Store sui prezzi', 'App Store pricing rules')], 0, L('Human Interface Guidelines.', 'Human Interface Guidelines.')),
            Q('h2', L('Che cosa significa gerarchia nelle HIG?', 'What does hierarchy mean in the HIG?'), [L('I controlli lasciano protagonista il contenuto', 'Controls leave content centre stage'), L('Il logo deve essere enorme', 'The logo must be huge'), L('I menu sono annidati in profondità', 'Menus are deeply nested'), L('Ogni schermata ha dieci pulsanti', 'Every screen has ten buttons')], 0, L('Il contenuto prima di tutto.', 'Content first.')),
            Q('h3', L('Perché usare i componenti di sistema?', 'Why use system components?'), [L('Seguono le HIG e si aggiornano con il sistema', 'They follow the HIG and update with the system'), L('Sono gli unici permessi', 'They are the only ones allowed'), L('Sono più colorati', 'They are more colourful'), L('Non hanno vantaggi', 'They have no advantages')], 0, L('Coerenza gratuita.', 'Consistency for free.')),
        ], task('text', L('Scrivi i tre principi del design Apple citati nella lezione, uno per riga con `-`.', 'Write the three Apple design principles mentioned in the lesson, one per line with `-`.'), "- \n- \n- ", [re('gerarch|hierarch', L('Gerarchia', 'Hierarchy')), re('armon|harmon', L('Armonia', 'Harmony')), re('coeren|consisten', L('Coerenza', 'Consistency'))], '', "- gerarchia\n- armonia\n- coerenza"), [
            dMatch(pMatch(), [[L('Gerarchia', 'Hierarchy'), L('Contenuto protagonista', 'Content centre stage')], [L('Armonia', 'Harmony'), L('In sintonia con l’hardware', 'In tune with hardware')], [L('Coerenza', 'Consistency'), L('Comportamenti già noti', 'Already-known behaviours')], ['SwiftUI', L('Framework per l’interfaccia', 'UI framework')], ['Liquid Glass', L('Materiali traslucidi', 'Translucent materials')]], L('Il design di Apple.', 'Apple’s design.')),
            dFlash(pFlash(), [[L('Le HIG coprono anche Apple Watch e Vision Pro', 'The HIG also cover Apple Watch and Vision Pro'), true], [L('Conviene cambiare il funzionamento dei controlli standard', 'It is wise to change how standard controls work'), false], [L('I componenti di sistema si aggiornano con iOS', 'System components update with iOS'), true], [L('Le HIG sono le regole dei prezzi dell’App Store', 'The HIG are App Store pricing rules'), false]], L('Linee guida Apple.', 'Apple guidelines.')),
        ]),
        lesson('navigation', L('Struttura e navigazione', 'Structure and navigation'), [
            P('Le app iOS usano tre schemi di navigazione: **gerarchica** con la **navigation bar** (scendi nel dettaglio, torni con il pulsante indietro in alto a sinistra o scorrendo dal bordo sinistro), **piatta** con la **tab bar** in basso (le sezioni principali, sempre visibili) e **guidata dal contenuto** (libri, giochi). Spesso si combinano: tab bar con una pila di navigazione in ogni tab.', 'iOS apps use three navigation styles: **hierarchical** with the **navigation bar** (drill into detail, go back with the top-left back button or by swiping from the left edge), **flat** with the bottom **tab bar** (main sections, always visible) and **content-driven** (books, games). They are often combined: a tab bar with a navigation stack in each tab.'),
            P('Le **schede modali** (sheet) salgono dal basso per compiti brevi e separati, con “Annulla” e “Fine”/“Salva” in alto; si possono chiudere trascinando giù. I **titoli grandi** (large title) a inizio schermata si riducono nella barra mentre scorri. Il tasto indietro mostra il titolo della schermata precedente.', '**Modal sheets** rise from the bottom for short, separate tasks, with “Cancel” and “Done”/“Save” at the top; they can be dismissed by dragging down. **Large titles** at the top of a screen shrink into the bar as you scroll. The back button shows the previous screen’s title.'),
            C('TabView {
  NavigationStack {
    List(ricette) { r in
      NavigationLink(r.nome) { DettaglioRicetta(r) }
    }
    .navigationTitle("Ricette")
  }
  .tabItem { Label("Ricette", systemImage: "book") }
}', 'swift'),
        ], [
            Q('n1', L('Come si torna indietro in una navigazione gerarchica iOS?', 'How do you go back in iOS hierarchical navigation?'), [L('Pulsante in alto a sinistra o scorrendo dal bordo', 'Top-left button or swiping from the edge'), L('Con un pulsante in basso a destra', 'With a bottom-right button'), L('Scuotendo il telefono', 'By shaking the phone'), L('Non si può', 'You cannot')], 0, L('Indietro da sinistra.', 'Back from the left.')),
            Q('n2', L('Dove sta la tab bar su iPhone?', 'Where is the tab bar on iPhone?'), [L('In basso', 'At the bottom'), L('In alto', 'At the top'), L('A destra', 'On the right'), L('Nascosta in un menu', 'Hidden in a menu')], 0, L('A portata di pollice.', 'Within thumb reach.')),
            Q('n3', L('Come si chiude una scheda modale?', 'How do you dismiss a modal sheet?'), [L('Con Annulla/Fine o trascinando giù', 'With Cancel/Done or dragging down'), L('Solo riavviando l’app', 'Only by restarting the app'), L('Con un doppio tocco sul logo', 'With a double tap on the logo'), L('Aspettando un minuto', 'By waiting a minute')], 0, L('Azioni in alto, gesto verso il basso.', 'Actions at the top, gesture downward.')),
        ], task('swift', L('Dai al `NavigationStack` il titolo “Ricette” con `.navigationTitle` e aggiungi alla tab il `.tabItem` con un `Label` e `systemImage`.', 'Give the `NavigationStack` the title “Ricette” with `.navigationTitle` and add the tab’s `.tabItem` with a `Label` and `systemImage`.'), "TabView {\n  NavigationStack {\n    List(ricette) { r in Text(r.nome) }\n  }\n}", [re('\.navigationTitle\(\s*"Ricette"\s*\)', L('Titolo della schermata', 'Screen title')), re('\.tabItem\s*\{[^}]*Label\([^)]*systemImage\s*:', L('Voce della tab con icona', 'Tab item with icon'))], '', "TabView {\n  NavigationStack {\n    List(ricette) { r in Text(r.nome) }\n      .navigationTitle(\"Ricette\")\n  }\n  .tabItem { Label(\"Ricette\", systemImage: \"book\") }\n}"), [
            dMatch(pMatch(), [['Navigation bar', L('Navigazione gerarchica', 'Hierarchical navigation')], ['Tab bar', L('Navigazione piatta', 'Flat navigation')], ['Sheet', L('Compito breve e separato', 'Short, separate task')], ['Large title', L('Titolo che si riduce scorrendo', 'Title that shrinks on scroll')]], L('Muoversi su iOS.', 'Moving around iOS.')),
            dOrder(pSort(), ['TabView {', '  NavigationStack {', '    List(ricette) { r in Text(r.nome) }', '  }', '}'], L('La tab contiene la pila di navigazione.', 'The tab contains the navigation stack.')),
        ]),
        lesson('type', L('SF Pro, Dynamic Type e SF Symbols', 'SF Pro, Dynamic Type and SF Symbols'), [
            P('Il carattere di sistema è **San Francisco** (SF Pro, con varianti Rounded e Mono, e New York per i testi con grazie). Gli **stili di testo** di sistema (`largeTitle`, `title`, `headline`, `body`, `callout`, `footnote`, `caption`) supportano il **Dynamic Type**: crescono e si riducono con la dimensione scelta dall’utente nelle impostazioni, fino alle misure per l’accessibilità. Il corpo predefinito è **17 pt**.', 'The system typeface is **San Francisco** (SF Pro, with Rounded and Mono variants, and New York for serif text). System **text styles** (`largeTitle`, `title`, `headline`, `body`, `callout`, `footnote`, `caption`) support **Dynamic Type**: they grow and shrink with the size the user chose in settings, up to accessibility sizes. The default body size is **17 pt**.'),
            P('**SF Symbols** è una libreria di migliaia di icone disegnate per allinearsi al testo SF: hanno pesi (da ultralight a black), scale (small, medium, large) e modalità di colore (monocromo, gerarchico, palette, multicolore), e alcune si animano. Si usano per nome: `Image(systemName: "heart.fill")`.', '**SF Symbols** is a library of thousands of icons designed to align with SF text: they have weights (ultralight to black), scales (small, medium, large) and colour modes (monochrome, hierarchical, palette, multicolour), and some animate. You use them by name: `Image(systemName: "heart.fill")`.'),
            C('Text("Pasta al pomodoro").font(.headline)
Text("20 minuti · facile").font(.subheadline).foregroundStyle(.secondary)
Image(systemName: "heart.fill").foregroundStyle(.red)', 'swift'),
        ], [
            Q('t1', L('Qual è il font di sistema di iOS?', 'What is the iOS system font?'), ['San Francisco (SF Pro)', 'Roboto', 'Segoe UI', 'Helvetica Neue'], 0, L('Con varianti Rounded e Mono.', 'With Rounded and Mono variants.')),
            Q('t2', L('Che cosa fa il Dynamic Type?', 'What does Dynamic Type do?'), [L('Adatta il testo alla dimensione scelta dall’utente', 'Adapts text to the user’s chosen size'), L('Anima le lettere', 'Animates letters'), L('Traduce il testo', 'Translates text'), L('Cambia font ogni giorno', 'Changes font every day')], 0, L('Accessibilità del testo.', 'Text accessibility.')),
            Q('t3', L('Come si mostra un simbolo SF in SwiftUI?', 'How do you show an SF Symbol in SwiftUI?'), [L('Image(systemName: "heart.fill")', 'Image(systemName: "heart.fill")'), L('Icon("heart")', 'Icon("heart")'), L('<img src="heart.svg">', '<img src="heart.svg">'), L('Symbol.load(heart)', 'Symbol.load(heart)')], 0, L('Per nome.', 'By name.')),
        ], task('swift', L('Mostra il titolo con lo stile `.headline` e sotto un `Image(systemName:)` con il simbolo `"star.fill"`.', 'Show the title with the `.headline` style and below it an `Image(systemName:)` with the `"star.fill"` symbol.'), "VStack {\n  Text(\"Preferiti\")\n}", [re('Text\([^)]*\)\s*\.font\(\s*\.headline\s*\)', L('Stile headline', 'Headline style')), re('Image\(\s*systemName\s*:\s*"star\.fill"\s*\)', L('Simbolo stella', 'Star symbol'))], '', "VStack {\n  Text(\"Preferiti\").font(.headline)\n  Image(systemName: \"star.fill\")\n}"), [
            dMatch(pMatch(), [['largeTitle', L('Titolo grande della schermata', 'Large screen title')], ['headline', L('Titolo di un elemento', 'Item heading')], ['body', L('Testo corrente, 17 pt', 'Running text, 17 pt')], ['caption', L('Didascalie piccole', 'Small captions')], ['SF Symbols', L('Icone allineate al testo', 'Icons aligned with text')]], L('Testo e simboli.', 'Text and symbols.')),
            dBug(pBug(), ['Text("Ricette")', '  .font(.system(size: 13))', 'Image(systemName: "book")'], 1, '  .font(.headline)', L('Una dimensione fissa ignora il Dynamic Type: meglio uno stile di sistema.', 'A fixed size ignores Dynamic Type: a system style is better.')),
        ]),
        lesson('color', L('Colori, materiali e accessibilità', 'Colours, materials and accessibility'), [
            P('iOS offre **colori di sistema** (`systemBlue`, `systemRed`…) e soprattutto **colori semantici** (`label`, `secondaryLabel`, `systemBackground`, `secondarySystemBackground`, `separator`) che cambiano da soli tra tema chiaro e scuro e con il contrasto aumentato. Il **colore d’accento** (tint) dell’app evidenzia gli elementi interattivi.', 'iOS offers **system colours** (`systemBlue`, `systemRed`…) and above all **semantic colours** (`label`, `secondaryLabel`, `systemBackground`, `secondarySystemBackground`, `separator`) that switch automatically between light and dark and with increased contrast. The app’s **accent colour** (tint) highlights interactive elements.'),
            P('I **materiali** (da ultraThin a thick) sono sfondi traslucidi e sfocati che danno profondità senza nascondere il contesto. Per l’**accessibilità**: target di almeno **44×44 pt**, etichette per **VoiceOver** sui controlli con sole icone, supporto a Dynamic Type, Riduci movimento e Aumenta contrasto. Le HIG raccomandano di testare con queste impostazioni attive.', '**Materials** (ultraThin to thick) are translucent, blurred backgrounds that add depth without hiding context. For **accessibility**: targets of at least **44×44 pt**, **VoiceOver** labels on icon-only controls, support for Dynamic Type, Reduce Motion and Increase Contrast. The HIG recommend testing with these settings turned on.'),
        ], [
            Q('c1', L('Che vantaggio hanno i colori semantici come `label`?', 'What is the advantage of semantic colours like `label`?'), [L('Si adattano da soli a tema scuro e contrasto', 'They adapt to dark mode and contrast by themselves'), L('Sono più saturi', 'They are more saturated'), L('Costano meno', 'They cost less'), L('Funzionano solo su Mac', 'They work only on Mac')], 0, L('Ruolo, non valore fisso.', 'Role, not fixed value.')),
            Q('c2', L('Qual è il target touch minimo nelle HIG?', 'What is the minimum touch target in the HIG?'), ['44×44 pt', '20×20 pt', '30×30 pt', '100×100 pt'], 0, L('Anche se l’icona è più piccola.', 'Even if the icon is smaller.')),
            Q('c3', L('Che cosa serve a un pulsante con solo un’icona per VoiceOver?', 'What does an icon-only button need for VoiceOver?'), [L('Un’etichetta di accessibilità', 'An accessibility label'), L('Un colore più acceso', 'A brighter colour'), L('Un’animazione', 'An animation'), L('Niente', 'Nothing')], 0, L('VoiceOver legge l’etichetta.', 'VoiceOver reads the label.')),
        ], task('swift', L('Al pulsante con l’icona del cestino aggiungi `.accessibilityLabel("Elimina")` e usa come colore di primo piano `.foregroundStyle(.red)`.', 'Add `.accessibilityLabel("Elimina")` to the bin icon button and use `.foregroundStyle(.red)` as the foreground colour.'), "Button(action: elimina) {\n  Image(systemName: \"trash\")\n}", [re('\.accessibilityLabel\(\s*"[^"]+"\s*\)', L('Etichetta per VoiceOver', 'VoiceOver label')), re('\.foregroundStyle\(\s*\.red\s*\)', L('Colore rosso', 'Red colour'))], '', "Button(action: elimina) {\n  Image(systemName: \"trash\")\n}\n.foregroundStyle(.red)\n.accessibilityLabel(\"Elimina\")"), [
            dMatch(pMatch(), [['label', L('Testo principale', 'Primary text')], ['secondaryLabel', L('Testo secondario', 'Secondary text')], ['systemBackground', L('Sfondo principale', 'Main background')], ['ultraThinMaterial', L('Sfondo traslucido sottile', 'Thin translucent background')], ['VoiceOver', L('Lettore di schermo', 'Screen reader')]], L('Colori e accessibilità iOS.', 'iOS colour and accessibility.')),
            dFlash(pFlash(), [[L('I colori semantici cambiano con il tema scuro', 'Semantic colours change with dark mode'), true], [L('Un pulsante solo icona non ha bisogno di etichetta', 'An icon-only button needs no label'), false], [L('I materiali traslucidi lasciano intravedere il contesto', 'Translucent materials let context show through'), true], [L('Le HIG sconsigliano di testare con Aumenta contrasto', 'The HIG advise against testing with Increase Contrast'), false]], L('Per tutti, su iOS.', 'For everyone, on iOS.')),
        ]),
    ],
